def backup(path: Path) -> None:
    dst = BACKUP / path.relative_to(ROOT)
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, dst)

def update_version(text: str, new_line: str) -> str:
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if line.startswith("Version de référence :"):
            lines[i] = new_line
            return "\n".join(lines) + ("\n" if text.endswith("\n") else "")
    return text

def append_once(path: Path, marker: str, section: str, version_line: str) -> None:
    text = path.read_text(encoding="utf-8")
    changed = False

    if marker not in text:
        text = text.rstrip() + "\n\n" + section.strip() + "\n"
        changed = True

    updated = update_version(text, version_line)
    if updated != text:
        text = updated
        changed = True

    if changed:
        backup(path)
        path.write_text(text, encoding="utf-8", newline="\n")
        print(f"[OK] Updated {path.relative_to(ROOT)}")
    else:
        print(f"[OK] Already up-to-date: {path.relative_to(ROOT)}")

def main() -> int:
    if not CDC.is_file():
        raise RuntimeError(f"Missing {CDC}")
    if not RECETTE.is_file():
        raise RuntimeError(f"Missing {RECETTE}")

    append_once(
        CDC,
        CDC_MARKER,
        CDC_SECTION,
        "Version de référence : R30 — Workflow Labs / ChordsLab.",
    )
    append_once(
        RECETTE,
        RECETTE_MARKER,
        RECETTE_SECTION,
        "Version de référence : R30 — recette Workflow Labs / ChordsLab.",
    )

    print(f"[OK] Backup: {BACKUP}")
    print("[OK] R30 CDC + recette applied.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
